<template>
  <section class="space-y-5 min-w-0" data-admin-orders>
    <h2 class="text-xl font-semibold">{{ ui(kind === 'Buyer' ? 'Đơn buyer' : 'Đơn supplier') }}</h2>
    <p class="text-sm text-slate-500">{{ ui('Theo dõi RFQ, báo giá và hợp đồng liên quan. Tạm dừng chỉ chặn báo giá mới hoặc sửa báo giá; lịch sử và hợp đồng đã tạo được giữ nguyên.') }}</p>
    <p v-if="notice" role="status" class="border border-amber-200 bg-amber-50 p-3 rounded-lg break-words">{{ ui(notice) }}</p>
    <form class="bg-white border rounded-xl p-4 grid md:grid-cols-4 gap-4" @submit.prevent="applyFilters">
      <label class="text-sm">{{ ui('Tìm đơn hàng') }}<input id="admin-order-query" v-model="filters.q" maxlength="120" class="block mt-1 w-full rounded-lg border-slate-300" /></label>
      <label class="text-sm">{{ ui('Trạng thái RFQ') }}<select id="admin-order-state" v-model="filters.state" class="block mt-1 w-full rounded-lg border-slate-300"><option value="">{{ ui('Tất cả') }}</option><option v-for="s in ['open','closed','cancelled']" :key="s" :value="s">{{ stateLabel(s) }}</option></select></label>
      <label class="text-sm">{{ ui('Tiếp nhận báo giá') }}<select id="admin-order-intake" v-model="filters.intake" class="block mt-1 w-full rounded-lg border-slate-300"><option value="">{{ ui('Tất cả') }}</option><option value="active">{{ ui('Đang tiếp nhận') }}</option><option value="paused">{{ ui('Tạm dừng nhận báo giá') }}</option></select></label>
      <button :disabled="busy" class="self-end bg-emerald-700 text-white rounded-lg px-4 py-2 disabled:opacity-50">{{ ui('Lọc đơn hàng') }}</button>
    </form>
    <p v-if="busy" role="status" class="text-sm">{{ ui('Đang tải') }}</p>
    <div class="bg-white border rounded-xl overflow-x-auto">
      <table class="w-full text-sm text-left"><thead class="bg-slate-50"><tr><th class="p-3">{{ ui('Tiêu đề') }}</th><th class="p-3">{{ ui('Tổ chức') }}</th><th class="p-3">{{ ui('Trạng thái RFQ') }}</th><th class="p-3">{{ ui('Tiếp nhận báo giá') }}</th><th class="p-3">{{ ui('Thao tác') }}</th></tr></thead>
        <tbody><tr v-for="row in list.items" :key="row._id" class="border-t"><td class="p-3 min-w-48 break-words">{{ row.title }}</td><td class="p-3">{{ row.organization?.name || '—' }}</td><td class="p-3">{{ stateLabel(row.state) }}</td><td class="p-3">{{ ui(row.quoteIntakeState === 'paused' ? 'Đang tạm dừng nhận báo giá' : 'Đang tiếp nhận') }}</td><td class="p-3"><button :disabled="busy" class="text-emerald-700 underline whitespace-nowrap" :data-order-id="row._id" @click="open(row._id)">{{ ui('Xem đơn hàng') }}</button></td></tr></tbody>
      </table><p v-if="!list.items.length && !busy" class="p-6 text-sm text-slate-500">{{ ui('Chưa có bản ghi.') }}</p>
    </div>
    <div class="flex flex-wrap items-center gap-4 text-sm"><span>{{ ui('Tổng bản ghi') }}: {{ list.total }} · {{ ui('Trang') }} {{ list.page }} / {{ list.pages || 1 }}</span><button :disabled="busy || list.page <= 1" class="underline disabled:opacity-40" @click="loadList(list.page - 1)">{{ ui('Trang trước') }}</button><button :disabled="busy || list.page >= list.pages" class="underline disabled:opacity-40" @click="loadList(list.page + 1)">{{ ui('Trang sau') }}</button></div>
    <section v-if="detail" class="bg-white border rounded-xl p-5 space-y-5" data-order-detail>
      <div class="flex flex-wrap gap-3 justify-between"><h3 class="text-lg font-semibold break-words">{{ detail.rfq.title }}</h3><button class="text-sm underline" @click="detail = null; history = null">{{ ui('Đóng chi tiết') }}</button></div>
      <p class="text-sm break-words">{{ detail.rfq.organization?.name }} · {{ detail.rfq.currency }} · {{ detail.rfq.incoterm }} · {{ detail.rfq.destination }}</p>
      <ul class="space-y-2 text-sm"><li v-for="line in rfqLines(detail.rfq)" :key="line.lineId" class="border p-3 rounded-lg break-words"><strong>{{ line.product }}</strong> · {{ line.quantity }} {{ line.unit }}<p class="whitespace-pre-wrap mt-1">{{ line.specifications }}</p></li></ul>
      <p v-if="detail.rfq.requirements" class="text-sm whitespace-pre-wrap break-words">{{ detail.rfq.requirements }}</p>
      <p v-if="detail.rfq.state !== 'open'" class="text-sm text-slate-500">{{ ui('RFQ đã đóng hoặc hủy. Không thay đổi tiếp nhận báo giá.') }}</p>
      <form v-else class="bg-slate-50 border rounded-lg p-4 space-y-3" @submit.prevent="changeIntake">
        <p class="text-sm font-medium">{{ ui(detail.rfq.quoteIntakeState === 'paused' ? 'Đang tạm dừng nhận báo giá' : 'Đang tiếp nhận') }} · {{ ui('Phiên bản cấu hình') }} {{ detail.rfq.quoteIntakeRevision || 0 }}</p>
        <label class="block text-sm" for="admin-order-reason">{{ ui('Lý do thay đổi tiếp nhận báo giá') }}</label><textarea id="admin-order-reason" v-model="reason" required minlength="5" maxlength="2000" class="w-full rounded-lg border-slate-300" />
        <button :disabled="busy" class="bg-emerald-700 text-white px-4 py-2 rounded-lg disabled:opacity-50">{{ ui(detail.rfq.quoteIntakeState === 'paused' ? 'Tiếp tục nhận báo giá' : 'Tạm dừng nhận báo giá') }}</button>
      </form>
      <section class="space-y-3"><h4 class="font-semibold">{{ ui('Báo giá liên quan') }} ({{ detail.quotes.total }})</h4><article v-for="quote in detail.quotes.items" :key="quote._id" class="border rounded-lg p-3 space-y-2 text-sm"><p>{{ quote.organization?.name }} · {{ ui('Phiên bản') }} {{ quote.version || 1 }} · {{ quote.state }}</p><p>{{ quote.quotedTotal }} {{ quote.currency }}</p><button :disabled="busy" class="text-emerald-700 underline" :data-quote-history="quote._id" @click="showHistory(quote._id)">{{ ui('Lịch sử báo giá') }}</button></article><div class="flex gap-4 text-sm"><button :disabled="busy || detail.quotes.page <= 1" class="underline disabled:opacity-40" @click="detailPage('quotePage', -1)">{{ ui('Báo giá trước') }}</button><button :disabled="busy || detail.quotes.page >= detail.quotes.pages" class="underline disabled:opacity-40" @click="detailPage('quotePage', 1)">{{ ui('Báo giá sau') }}</button></div></section>
      <section v-if="history" class="border border-emerald-200 rounded-lg p-4 space-y-4"><div class="flex justify-between gap-3"><h4 class="font-semibold">{{ ui('Lịch sử báo giá') }}</h4><button class="text-sm underline" @click="history = null">{{ ui('Đóng lịch sử') }}</button></div><article v-for="version in history.items" :key="version.version" class="border-t pt-3"><p v-if="version.legacyDerived" class="text-sm text-amber-800">{{ ui('Bản suy ra từ báo giá cũ hiện tại; chưa có bằng chứng lịch sử phiên bản đã lưu.') }}</p><QuoteSnapshot :snapshot="version.payload" /></article><div class="flex gap-4 text-sm"><button :disabled="busy || history.page <= 1" class="underline disabled:opacity-40" @click="showHistory(historyQuote, history.page - 1)">{{ ui('Trang trước') }}</button><button :disabled="busy || history.page >= history.pages" class="underline disabled:opacity-40" @click="showHistory(historyQuote, history.page + 1)">{{ ui('Trang sau') }}</button></div></section>
      <section class="space-y-3"><h4 class="font-semibold">{{ ui('Hợp đồng liên quan') }} ({{ detail.trades.total }})</h4><article v-for="trade in detail.trades.items" :key="trade._id" class="border rounded-lg p-3 space-y-2 text-sm"><p class="font-medium break-words">{{ trade.title }}</p><p>{{ trade.buyer?.name }} → {{ trade.supplier?.name }} · {{ trade.state }} · {{ trade.amount }} {{ trade.asset }}</p><p v-if="trade.quoteSnapshot">{{ ui('Phiên bản báo giá đã chụp') }}: {{ trade.quoteSnapshot.version }}</p><p class="break-all text-xs text-slate-500">{{ ui('Hash điều khoản') }}: {{ trade.termsHash }}</p><details v-if="trade.quoteSnapshot"><summary class="cursor-pointer text-emerald-700">{{ ui('Xem bản chụp báo giá') }}</summary><QuoteSnapshot class="mt-3" :snapshot="trade.quoteSnapshot" /></details></article><div class="flex gap-4 text-sm"><button :disabled="busy || detail.trades.page <= 1" class="underline disabled:opacity-40" @click="detailPage('tradePage', -1)">{{ ui('Hợp đồng trước') }}</button><button :disabled="busy || detail.trades.page >= detail.trades.pages" class="underline disabled:opacity-40" @click="detailPage('tradePage', 1)">{{ ui('Hợp đồng sau') }}</button></div></section>
      <section class="space-y-3"><h4 class="font-semibold">{{ ui('Nhật ký tiếp nhận báo giá') }} ({{ detail.decisions.total }})</h4><article v-for="decision in detail.decisions.items" :key="decision._id" class="text-sm border rounded-lg p-3 space-y-2"><p>{{ ui('Phiên bản cấu hình') }} {{ decision.revision }} · {{ ui(decision.state === 'paused' ? 'Đang tạm dừng nhận báo giá' : 'Đang tiếp nhận') }} · {{ date(decision.createdAt) }}</p><p class="whitespace-pre-wrap break-words">{{ decision.reason }}</p><p class="text-xs text-slate-500 break-all">{{ ui('Tài khoản thực hiện') }}: {{ decision.actor }}</p></article><div class="flex gap-4 text-sm"><button :disabled="busy || detail.decisions.page <= 1" class="underline disabled:opacity-40" @click="detailPage('decisionPage', -1)">{{ ui('Nhật ký trước') }}</button><button :disabled="busy || detail.decisions.page >= detail.decisions.pages" class="underline disabled:opacity-40" @click="detailPage('decisionPage', 1)">{{ ui('Nhật ký sau') }}</button></div></section>
    </section>
  </section>
</template>
<script setup lang="ts">
import { rfqLines } from '~/lib/quotations';
const props = defineProps<{ kind: 'Buyer' | 'Supplier' }>();
const { request } = usePlatform(), { ui } = useWorkspaceText(), { locale } = useI18n();
const filters = reactive({ q:'',state:'',intake:'' }), applied = ref({ q:'',state:'',intake:'' });
const list = ref<any>({items:[],total:0,page:1,pages:0}), detail = ref<any>(null), history = ref<any>(null), historyQuote = ref(''), reason = ref(''), notice = ref(''), busy = ref(false);
const detailPaging = reactive({quotePage:1,tradePage:1,decisionPage:1});
const stateLabel = (s:string) => ui(({open:'Đang mở',closed:'Đã đóng',cancelled:'Đã hủy'} as Record<string,string>)[s] || s);
const date = (s:string) => new Date(s).toLocaleString(locale.value === 'en' ? 'en-GB' : 'vi-VN');
const params = (value:Record<string,unknown>) => new URLSearchParams(Object.entries(value).filter(([,v])=>v!=='' && v!==undefined).map(([k,v])=>[k,String(v)])).toString();
const errorText = (e:any) => e.data?.error?.message || e.message;
async function loadList(page=1) { if(busy.value)return;busy.value=true;notice.value='';try{list.value=await request('/platform/admin/orders?'+params({kind:props.kind,page,...applied.value}));}catch(e:any){notice.value=errorText(e);}finally{busy.value=false;} }
async function applyFilters(){applied.value={...filters};detail.value=null;history.value=null;await loadList();}
async function fetchDetail(id:string){detail.value=await request('/platform/admin/orders/'+id+'?'+params(detailPaging));}
async function open(id:string){if(busy.value)return;busy.value=true;notice.value='';history.value=null;reason.value='';Object.assign(detailPaging,{quotePage:1,tradePage:1,decisionPage:1});try{await fetchDetail(id);}catch(e:any){notice.value=errorText(e);}finally{busy.value=false;}}
async function detailPage(key:'quotePage'|'tradePage'|'decisionPage',change:number){if(busy.value)return;busy.value=true;detailPaging[key]+=change;try{await fetchDetail(detail.value.rfq._id);}catch(e:any){detailPaging[key]-=change;notice.value=errorText(e);}finally{busy.value=false;}}
async function showHistory(id:string,page=1){if(busy.value)return;busy.value=true;try{history.value=await request(`/platform/admin/orders/${detail.value.rfq._id}/quotes/${id}/versions?page=${page}`);historyQuote.value=id;}catch(e:any){notice.value=errorText(e);}finally{busy.value=false;}}
async function changeIntake(){if(busy.value)return;busy.value=true;notice.value='';try{await request(`/platform/admin/orders/${detail.value.rfq._id}/intake`,'POST',{state:detail.value.rfq.quoteIntakeState==='paused'?'active':'paused',expectedRevision:detail.value.rfq.quoteIntakeRevision||0,reason:reason.value});reason.value='';detailPaging.decisionPage=1;await fetchDetail(detail.value.rfq._id);list.value=await request('/platform/admin/orders?'+params({kind:props.kind,page:list.value.page,...applied.value}));notice.value='Đã cập nhật tiếp nhận báo giá.';}catch(e:any){notice.value=errorText(e);}finally{busy.value=false;}}
onMounted(()=>loadList());
</script>
